class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return 0
        return haystack.rfind(needle)

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return 0
        return haystack.count(needle)

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return 0
        for start in range(len(haystack) - len(needle)):
            if haystack[start:start + len(needle)] == needle:
                return start
        return -1

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return -1
        return haystack.find(needle)

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return 0
        for start in range(len(haystack) - len(needle) + 1):
            if haystack[start:start + len(needle)] != needle:
                return start
        return -1

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return 0
        for start in range(len(haystack) - len(needle) + 1):
            if haystack[start:start + len(needle)] == needle:
                return start + 1
        return -1

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return 0
        for start in range(len(haystack) - len(needle) + 1):
            if haystack[start:start + len(needle) - 1] == needle:
                return start
        return -1

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return 0
        for start in range(1, len(haystack) - len(needle) + 1):
            if haystack[start:start + len(needle)] == needle:
                return start
        return -1

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if needle == '':
            return 0
        for start in range(len(haystack) - len(needle) + 1):
            if haystack[start:start + len(needle)] == needle:
                return start
        return len(haystack)

